# 128 neurons = 1 MXU tile = ZERO padding waste
N_S, N_EXC, N_INH, N_M = 32, 48, 16, 32
N = 128  # 32+48+16+32
TICKS = 10
EPOCHS = 5
POP = 32768

print(f"JAX on: {jax.devices()}")
print(f"MXU-128 | Pop={POP} | {EPOCHS} inner epochs | {TICKS} ticks/tok")

