B2 = jnp.array([-0.16188499,0.02284577,-0.19403875,-0.15360010,-0.03054354,0.21870774,-0.22587144,-0.01386520,0.08850682,-0.07660323,0.08169022,0.04029652,0.01114514,-0.16100746,-0.08803931,-0.01812577], dtype=jnp.float32)
W3 = jnp.array([[-0.14968145],[0.13770869],[-0.04906771],[0.19960940],[0.06822094],[0.05445930],[0.07109693],[0.18540233],[0.08508104],[0.09746680],[-0.23635584],[-0.19301182],[-0.14879906],[0.21384695],[0.19163543],[0.20750341]], dtype=jnp.float32)
B3 = jnp.array([0.03195196], dtype=jnp.float32)

def mlp_scalar(tr_pre, tr_post, tr_ca, reward):
    x = jnp.array([jnp.mean(tr_pre), jnp.mean(tr_post), jnp.mean(tr_ca), reward])
    return (jnp.maximum(0.0, jnp.maximum(0.0, x @ W1 + B1) @ W2 + B2) @ W3 + B3)[0]

# ---- Topology (shared, not per-brain) ----
TEXT = "HELLO WORLD THIS IS RRA"
toks = jnp.array([ord(c) for c in TEXT], dtype=jnp.int32)
n_tok = len(TEXT)
grid = jnp.array([[(i%16)/15.0, (i//16)/15.0] for i in range(256)], dtype=jnp.float32)

key = random.PRNGKey(42)
key, k1, k2 = random.split(key, 3)
topo = random.bernoulli(k1, 0.15, (N, N)).astype(jnp.float32)
# Force dense sensory→motor shortcut (guaranteed signal path)
topo = topo.at[:N_S, N-N_M:].set(1.0)
# Dale's Law masks: EXC sources = sensory+exc_hidden+motor, INH sources = inh_hidden
EXC_SRC = jnp.concatenate([jnp.ones(N_S+N_EXC), jnp.zeros(N_INH), jnp.ones(N_M)])  # (128,)
INH_SRC = jnp.concatenate([jnp.zeros(N_S+N_EXC), jnp.ones(N_INH), jnp.zeros(N_M)])  # (128,)
# Population rate coding: no motor_seeds needed
MAX_SPIKES = float(TICKS)  # max spikes per neuron per token

@jit
def sim(genome):
    sg, ba, ws, aj, gd, lr, to, tm = genome
    gd_neg = -jnp.abs(gd)
    vth = -56.5 + to
    # Fused E/I sign mask: one matmul per tick (TPU-optimal)
    sign = EXC_SRC * aj + INH_SRC * gd_neg  # (128,) broadcast
    W = topo * ws  # unsigned weights

    def proc_tok(st, ti):
        v, Wc, bd, tp, tpo, tca, aloss, asp = st
        co = grid[ti]
        bd2 = (1.0 - ba) * bd + ba * co
        ramp = jnp.linspace(0.0, 1.0, N_S//2)
        iext = jnp.concatenate([jnp.where(ramp < bd2[0], 1.0, 0.0),
                                jnp.where(ramp < bd2[1], 1.0, 0.0),
                                jnp.zeros(N - N_S)]) * sg
        def tick(ts, _):
            tv, tsp, ma = ts
            tv = -70.0 + (tv + 70.0) * jnp.exp(-1.0 / tm)
            # ONE matmul: W_signed = Wc * sign[:, None] fused by XLA
            tv += iext + jnp.dot(tsp, Wc * sign[:, None])
            ns = jnp.where(tv >= vth, 1.0, 0.0)
            return (jnp.where(ns > 0.5, -75.0, tv), ns, ma + ns[-N_M:]), ns

        (v, _, msum), allsp = lax.scan(tick, (v, jnp.zeros(N), jnp.zeros(N_M)), jnp.arange(TICKS))

        # Population rate coding: first 16 motor = X, last 16 = Y
        mx = jnp.mean(msum[:N_M//2]) / MAX_SPIKES  # [0, 1]
        my = jnp.mean(msum[N_M//2:]) / MAX_SPIKES  # [0, 1]
        mout = jnp.array([jnp.clip(mx, 0.0, 1.0), jnp.clip(my, 0.0, 1.0)])
        tdist = jnp.sum((mout - co)**2)
        dists = jnp.sum((grid - mout[None, :])**2, axis=1)
        reward = jnp.where(jnp.argmin(dists) == ti, 1.0, -1.0)

        # Traces
        ss = jnp.sum(allsp, axis=0)
        tp = tp * jnp.exp(-TICKS/11.0) + ss
        tpo = tpo * jnp.exp(-TICKS/11.0) + ss
        tca = tca * jnp.exp(-TICKS/5.3) + ss * 10.0

        # MLP-gated Hebbian (only excitatory rows learn)
        pm = mlp_scalar(tp, tpo, tca, reward)
        pp = jnp.concatenate([jnp.zeros(N - N_M), msum / float(TICKS)])
        dw = pm * jnp.outer(tp, pp) * lr * topo * EXC_SRC[:, None]
        Wn = jnp.clip(Wc + dw, 0.0, 5.0)

        return (v, Wn, bd2, tp, tpo, tca, aloss + tdist, asp + jnp.sum(allsp)), None

    def epoch(st, _):
        fst, _ = lax.scan(proc_tok, st, toks)
        # Reset dynamics, keep weights
        return (jnp.full((N,), -70.0), fst[1], jnp.array([0.5, 0.5]),
                jnp.zeros(N), jnp.zeros(N), jnp.zeros(N), 0.0, fst[7]), fst[6]

    init = (jnp.full((N,), -70.0), W, jnp.array([0.5, 0.5]),
            jnp.zeros(N), jnp.zeros(N), jnp.zeros(N), 0.0, 0.0)
    final, eloss = lax.scan(epoch, init, jnp.arange(EPOCHS))

    # Fitness = last epoch loss (lower = better learning)
    last_l = eloss[-1] / n_tok
    tsp = final[7]
    ideal = N * TICKS * n_tok * EPOCHS * 0.05
    r = tsp / (ideal + 1.0)
    pen = jnp.where(r < 0.1, 50.0, 0.0) + jnp.where(r > 3.0, 20.0, 0.0) + (r - 1.0)**2 * 2.0
    return last_l + pen, tsp

sim_pop = jit(vmap(sim))

@jit
def mutate(g, k):
    n = random.normal(k, g.shape) * 0.15
    return jnp.clip(g + g * n,
                    jnp.array([1,0.01,0.01,0.1,0.1,0.001,-10,5]),
                    jnp.array([200,0.99,5.0,50,50,2.0,10,100]))

def run():
    rng = random.PRNGKey(777)
    base = jnp.array([30.0, 0.3, 0.5, 8.0, 8.0, 0.05, 0.0, 22.0])
    rng, sk = random.split(rng)
    gs = mutate(jnp.tile(base, (POP, 1)), sk)

    for gen in range(80):
        t0 = time.time()
        fit, sp = sim_pop(gs)
        rank = jnp.argsort(fit)
        bi = rank[0]
        dt = time.time() - t0
        print(f"Gen {gen+1:03d} | Loss: {float(fit[bi]):.4f} | Spk: {float(sp[bi]):.0f} | {dt:.1f}s | Best: {gs[bi]}")

        top = gs[rank[:POP//10]]
        nov = gs[rank[-POP//10:]]
        parents = jnp.concatenate([top, nov])
        rng, sk = random.split(rng)
        gs = mutate(jnp.tile(parents, (POP // parents.shape[0], 1)), sk)
        if fit[bi] < 0.01: break

    print(f"\n=== FINAL GENOME ===\n{gs[rank[0]]}")

if __name__ == "__main__":
    run()
